// Spring Cloud Contract DSL example (contracts/shouldReturnUser.groovy)
org.springframework.cloud.contract.spec.Contract.make {
    request {
        method GET()
        url '/users/1'
    }
    response {
        status OK()
        body(id: 1, name: 'John Doe')
        headers {
            contentType('application/json')
        }
    }
}
